PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?publisher_name ?diff
WHERE {
  {
    SELECT (COUNT(?h1) AS ?dc) WHERE {
      ?h1 a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero> ;
          <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?p1 .
      ?p1 <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Publisher/publisher_name> "DC Comics" .
    }
  }
  {
    SELECT (COUNT(?h2) AS ?marvel) WHERE {
      ?h2 a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero> ;
          <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?p2 .
      ?p2 <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Publisher/publisher_name> "Marvel Comics" .
    }
  }
  BIND(IF(xsd:integer(?dc) > xsd:integer(?marvel), "DC Comics", "Marvel Comics") AS ?publisher_name)
  BIND(ABS(xsd:integer(?dc) - xsd:integer(?marvel)) AS ?diff)
}

SELECT (COUNT(?hero) AS ?n) WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero> .
  OPTIONAL { ?hero <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/full_name> ?fn }
  FILTER(!BOUND(?fn) || ?fn = "-")
}

SELECT (AVG(?weight) AS ?avgWeight) WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/gender_id> ?genderId ;
        <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/weight_kg> ?weight .
  ?gender a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Gender> ;
          <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Gender/id> ?genderId ;
          <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Gender/gender> "Female" .
  FILTER (xsd:decimal(?weight) > 0)
}

SELECT ?race WHERE {
  ?s a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero> ;
     <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/superhero_name> "Copycat" ;
     <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/race_id> ?rid .
  ?r a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Race> ;
     <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Race/id> ?rid ;
     <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Race/race> ?race .
