ORDER BY DESC(xsd:integer(?height_cm))

SELECT ?superhero_name WHERE {
  ?p a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Publisher> ;
     <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Publisher/publisher_name> "Marvel Comics" .
