      ?h a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero> ;
         <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/weight_kg> ?w .
      FILTER(xsd:decimal(?w) > 0)
    }
  }
  ?s a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero> ;
     <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/weight_kg> ?sw ;
