     <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/hasGender> ?g .
  ?g <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Gender/gender> "Male" .
  FILTER(xsd:decimal(?sw) > xsd:decimal(?avgW) * 0.79)
