SELECT ?colour (COUNT(?hero) AS ?count) WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/publisher_id> ?pub ;
        <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/eye_colour_id> ?eyeColourId .
  ?publisher a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Publisher> ;
             <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Publisher/id> ?pub ;
             <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Publisher/publisher_name> "Marvel Comics" .
  ?colourEntity a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Colour> ;
                <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Colour/id> ?eyeColourId ;
                <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Colour/colour> ?colour .
}
GROUP BY ?colour
ORDER BY DESC(?count)

SELECT (100.0 * SUM(IF(?pname = "Marvel Comics", 1, 0)) / COUNT(?h) AS ?percentage)
WHERE {
  ?h a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero> ;
     <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/height_cm> ?height ;
     <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?p .
  ?p <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Publisher/publisher_name> ?pname .
  FILTER(xsd:decimal(?height) >= 150 && xsd:decimal(?height) <= 180)
}

SELECT ?percentage ?marvel_count WHERE {
  {
    SELECT (COUNT(?h) AS ?total)
           (SUM(IF(?al = "Neutral", 1, 0)) AS ?neutralCount)
           (SUM(IF(?al = "Neutral" && ?pub = "Marvel Comics", 1, 0)) AS ?marvel_count)
    WHERE {
      ?h a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero> ;
         <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/hasAlignment> ?a .
      ?a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Alignment/alignment> ?al .
      OPTIONAL {
        ?h <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?p .
        ?p <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Publisher/publisher_name> ?pub .
      }
    }
  }
  BIND(xsd:decimal(?neutralCount) / xsd:decimal(?total) * 100 AS ?percentage)
}

SELECT ?publisher_name WHERE {
  ?attr a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Attribute> ;
        <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Attribute/attribute_name> "Speed" .
  ?ha a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/HeroAttribute> ;
      <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/HeroAttribute/hasAttribute> ?attr ;
      <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/HeroAttribute/hasSuperhero> ?hero ;
      <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/HeroAttribute/attribute_value> ?val .
  ?hero <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?pub .
  ?pub <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Publisher/publisher_name> ?publisher_name .
}
ORDER BY xsd:long(?val)
LIMIT 1

