     <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/eye_colour_id> ?c .
  ?g a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Gender> ;
     <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Gender/gender> "Female" .
  ?c a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Colour> ;
     <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Colour/colour> ?colour .
}

SELECT ?height_cm WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/eye_colour_id> ?colourId ;
        <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Superhero/height_cm> ?height_cm .
  ?colour a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Colour> ;
          <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Colour/id> ?colourId ;
          <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Colour/colour> ?colourName .
  FILTER(?colourName = "Amber")
}

SELECT (COUNT(?hero) AS ?n) WHERE {
  {
    SELECT (MAX(?v) AS ?maxVal) WHERE {
      ?ha a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/HeroAttribute> ;
          <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/HeroAttribute/hasAttribute> ?attr ;
          <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/HeroAttribute/attribute_value> ?v .
      ?attr <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Attribute/attribute_name> "Strength" .
    }
  }
  ?ha2 a <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/HeroAttribute> ;
       <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/HeroAttribute/hasAttribute> ?attr2 ;
       <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/HeroAttribute/hasSuperhero> ?hero ;
       <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/HeroAttribute/attribute_value> ?v2 .
  ?attr2 <http://bird-bird_superhero-ontology-20260809-235515/ontology/vkg-bird_superhero/Attribute/attribute_name> "Strength" .
  FILTER(xsd:decimal(?v2) = ?maxVal)
}

